from pathlib import Path
import json,difflib,shutil
H=Path(__file__).resolve().parent;P=H.parent/'tex-streaming-lexer-28';C=H/'candidate';N=C/'examples/gpu-math/native-vkf'
C.mkdir(exist_ok=True)
for p in (P/'candidate').rglob('*'):
 if p.is_file():
  q=C/p.relative_to(P/'candidate');q.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(p,q)
rows=[]
def case(name,raw,tokens,assign=()):
 rows.append(dict(id=name,raw=raw,tokens=tokens,assign=assign))
# token rows: kind, category, value, byte start, byte stop, provenance, origin.
def t(k,c,v,a,b,p=0,o=None):return [k,c,v,a,b,p,o]
case('trimmed_eof','a ',[t(1,11,'a',0,1,o=0),t(1,10,' ',1,2,1,1)])
case('spaces_only_eof','  ',[t(2,-1,'par',0,2,1,0)])
case('escape_trimmed_eof','\\ ',[t(2,-1,'\r',0,2,1,0)])
case('escape_zero_unit','\\',[t(2,-1,'\r',0,1,1,0)])
case('zero_unit_eof','a',[t(1,11,'a',0,1,o=0),t(1,10,' ',1,1,1,-1)])
case('tab_not_trimmed','a\t',[t(1,11,'a',0,1),t(1,10,' ',1,2)])
case('trailing_tab_other','a\t',[t(1,11,'a',0,1),t(1,12,'\t',1,2),t(1,10,' ',2,2,1,-1)],[(9,12)])
case('trim_before_custom_active','a  ',[t(1,11,'a',0,1),t(1,10,' ',1,3,1)],[(32,13)])
case('space_after_comment','a%α^^A\n b',[t(1,11,'a',0,1),t(1,11,'b',9,10),t(1,10,' ',10,10,1,-1)])
case('comment_then_blank','a%z\n\nb',[t(1,11,'a',0,1),t(2,-1,'par',4,5,1),t(1,11,'b',5,6),t(1,10,' ',6,6,1,-1)])
case('comment_crlf','a%z\r\n b',[t(1,11,'a',0,1),t(1,11,'b',6,7),t(1,10,' ',7,7,1,-1)])
case('bare_cr_then_lf','a\r\r\nb',[t(1,11,'a',0,1),t(1,10,' ',1,2,1),t(2,-1,'par',2,4,1),t(1,11,'b',4,5),t(1,10,' ',5,5,1,-1)])
case('escaped_ignored','\\\0 x',[t(2,-1,'\0',0,2),t(1,10,' ',2,3),t(1,11,'x',3,4),t(1,10,' ',4,4,1,-1)])
case('escaped_invalid','\\\x7f x',[t(2,-1,'\x7f',0,2),t(1,10,' ',2,3),t(1,11,'x',3,4),t(1,10,' ',4,4,1,-1)])
case('escaped_active','\\~ x',[t(2,-1,'~',0,2),t(1,10,' ',2,3),t(1,11,'x',3,4),t(1,10,' ',4,4,1,-1)])
case('custom_space_control','\\! x',[t(2,-1,'!',0,2),t(1,11,'x',3,4),t(1,10,' ',4,4,1,-1)],[(33,10)])
case('custom_space_canonical','a!b',[t(1,11,'a',0,1),t(1,10,' ',1,2),t(1,11,'b',2,3),t(1,10,' ',3,3,1,-1)],[(33,10)])
case('custom_comment','a!α\n b',[t(1,11,'a',0,1),t(1,11,'b',6,7),t(1,10,' ',7,7,1,-1)],[(33,14)])
case('custom_ignore_state','a! b',[t(1,11,'a',0,1),t(1,10,' ',2,3),t(1,11,'b',3,4),t(1,10,' ',4,4,1,-1)],[(33,9)])
case('control_word_ignore_boundary','\\a\0b',[t(2,-1,'a',0,2),t(1,11,'b',3,4),t(1,10,' ',4,4,1,-1)])
case('control_word_comment','\\a%α\n x',[t(2,-1,'a',0,2),t(1,11,'x',7,8),t(1,10,' ',8,8,1,-1)])
case('escape_newline_leading_space','\\\n x',[t(2,-1,'\r',0,2,1),t(1,11,'x',3,4),t(1,10,' ',4,4,1,-1)])
case('control_symbol_newline','\\%\nx',[t(2,-1,'%',0,2),t(1,10,' ',2,3,1),t(1,11,'x',3,4),t(1,10,' ',4,4,1,-1)])
case('profile_formfeed_other','\f',[t(1,12,'\f',0,1),t(1,10,' ',1,1,1,-1)])
(H/'boundary-cases.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
# Local string emitter follows existing repository escapes, including literal $.
def lit(s):
 if any(ord(c)<32 and c not in '\t\r\n' for c in s):
  return '&'.join('str(chr(%d))'%ord(c) if ord(c)<32 and c not in '\t\r\n' else lit(c) for c in s)
 return json.dumps(s,ensure_ascii=False).replace('$','\\$')
lines=['# TMR30 independently specified boundary regressions; NATIVE UNEXECUTED.'];names=[]
for row in rows:
 name='review30_'+row['id'];names.append(name)
 lines += [name+'()->bit:','    source:table('+lit(row['raw'])+')','    trace:origins()','    state:m.open(source,trace,0)','    cats:m.categories()']
 for code,cat in row['assign']:lines += [f'    .cats:m.assign(cats,{code},{cat})']
 lines+=['    step:m.next(source,trace,state,cats)']
 for i,(kind,cat,value,a,b,prov,origin) in enumerate(row['tokens']):
  if i:lines+=['    .step:m.next(source,step.origins,step.state,cats)']
  terms=[f'step.diagnostic=0',f'step.token.kind={kind}',f'step.token.category= {cat}',f'step.token.value={lit(value)}',f'step.token.start={a}',f'step.token.stop={b}',f'step.token.provenance={prov}']
  if origin is not None:terms.append(f'step.token.origin= {origin}')
  lines+=['    ('+' /\\ '.join(terms)+')?! "'+name+' token '+str(i)+'"']
 lines+=['    .step:m.next(source,step.origins,step.state,cats)','    (step.diagnostic=0 /\\ step.token.kind=0)?! "review30 EOF"','    @:true','']
extra=r'''
review30_rollback_after_comment()->bit:
    source:table("a%α\n "+str(chr(127)))
    trace:origins()
    cats:m.categories()
    first:m.next(source,trace,m.open(source,trace,0),cats)
    failed:m.next(source,first.origins,first.state,cats)
    (failed.diagnostic=3 /\ failed.token.start=6 /\ failed.token.stop=7)?! "offending scalar, not saved cursor"
    m.reusable(first.state,failed.state,cats,cats,first.origins,failed.origins)?! "all cursor/prefix columns rollback"
    changed:m.assign(cats,127,12)
    retried:m.next(source,failed.origins,failed.state,changed)
    (retried.diagnostic=0 /\ retried.token.start=6 /\ retried.token.category=12 /\ retried.token.origin=1)?! "retry replays skipped comment without duplicate origins"
    (first.origins.source.length()=1 /\ first.token.category=11)?! "retained value ownership"
    @:true

review30_unicode_lookahead_rollback()->bit:
    source:table("x\\aα")
    trace:origins()
    cats:m.categories()
    first:m.next(source,trace,m.open(source,trace,0),cats)
    failed:m.next(source,first.origins,first.state,cats)
    (failed.diagnostic=1 /\ failed.token.start=3 /\ failed.token.stop=5)?! "UTF8 lookahead exact bytes"
    m.reusable(first.state,failed.state,cats,cats,first.origins,failed.origins)?! "partial control word not committed"
    @:true

review30_translation_retry()->bit:
    source:table("x\\ab^^63")
    trace:origins()
    cats:m.categories()
    first:m.next(source,trace,m.open(source,trace,0),cats)
    failed:m.next(source,first.origins,first.state,cats)
    (failed.diagnostic=2 /\ failed.token.start=4 /\ failed.token.stop=5)?! "translation lookahead"
    m.reusable(first.state,failed.state,cats,cats,first.origins,failed.origins)?! "translation rollback"
    changed:m.assign(cats,94,12)
    retried:m.next(source,failed.origins,failed.state,changed)
    (retried.diagnostic=0 /\ retried.token.value="ab" /\ retried.token.start=1 /\ retried.token.stop=4)?! "assignment before retry"
    @:true

review30_lookahead_category_feedback()->bit:
    source:table("\\a@ b")
    trace:origins()
    cats:m.categories()
    word:m.next(source,trace,m.open(source,trace,0),cats)
    changed:m.assign(cats,64,13)
    next:m.next(source,word.origins,word.state,changed)
    (word.token.value="a" /\ next.token.kind=3 /\ next.token.category=13)?! "lookahead category not retained"
    (cats.values.(64)=12 /\ changed.values.(64)=13)?! "old category checkpoint remains immutable"
    (~m.reusable(word.state,word.state,cats,changed,word.origins,word.origins))?! "category invalidation"
    same:m.assign(cats,64,12)
    (~m.reusable(word.state,word.state,cats,same,word.origins,word.origins))?! "same value assignment invalidates generation"
    @:true

review30_comment_feedback()->bit:
    source:table("\\a%z\n x")
    trace:origins()
    cats:m.categories()
    word:m.next(source,trace,m.open(source,trace,0),cats)
    changed:m.assign(cats,37,12)
    percent:m.next(source,word.origins,word.state,changed)
    (percent.token.value="%" /\ percent.token.category=12 /\ percent.token.start=2)?! "comment dispatch after assignment"
    @:true
'''
names+=['review30_rollback_after_comment','review30_unicode_lookahead_rollback','review30_translation_retry','review30_lookahead_category_feedback','review30_comment_feedback']
s=(N/'tex_streaming_mouth_tests.vkf').read_text();assert s.endswith('renderer_tests()\n')
s=s[:-len('renderer_tests()\n')]+ '\n'.join(lines)+extra+'\nreview30_tests()->bit:\n'+''.join('    '+name+'()?! "'+name+'"\n' for name in names)+'    @:true\n\nrenderer_tests()\nreview30_tests()\n'
(N/'tex_streaming_mouth_tests.vkf').write_text(s)
p=N/'tex_streaming_mouth.vkf';s=p.read_text();old='# Unit spans retain physical terminator/trailing bytes. At unterminated EOF\n# virtual CR has a zero-width anchor and can NEVER acquire an authored origin.'
new='# Unit spans retain physical terminator/trailing bytes, even at unterminated EOF.\n# A virtual CR unit is zero-width ONLY when no trailing bytes remain. Escaping\n# it still produces a nonempty composite token span. All these tokens retain\n# provenance=1: an origin anchor is never proof of authored token spelling.'
assert old in s;p.write_text(s.replace(old,new))
base_contract=(P/'MOUTH-CONTRACT.txt').read_text()
old='A virtual EOF\nendline has an empty anchor and origin=-1.'
new='A virtual EOF\nendline unit has an empty anchor only when no trimmed trailing spaces remain.\nFor raw "a " without a physical terminator, its engine-derived space has span\n[1,2) and an origin; raw " " produces par with span [0,1) and an origin. A bare\nEOF endline after raw "a" has span [1,1) and origin=-1. Escaping even a zero-width\nunit produces a nonempty composite control-token span covering the escape.\nEvery such token has provenance=1, regardless of whether origin is -1.'
assert old in base_contract
base_contract=base_contract.replace(old,new).replace('This is neither Unicode TeX nor an INITEX bootstrap. Default categories:', 'This is neither Unicode TeX nor an INITEX bootstrap, nor an exact plain/LaTeX\nformat snapshot: for example ASCII FF stays category12, whereas plain.tex\nsets it active and defines its meaning. Default categories:')
(H/'MOUTH-CONTRACT-reviewed.txt').write_text(base_contract)
patch=[];combined=[]
for p in sorted(C.rglob('*')):
 if not p.is_file():continue
 rel=p.relative_to(C).as_posix();before=(P/'candidate'/rel).read_text();after=p.read_text()
 if before!=after:
  patch.append(f'diff --git a/{rel} b/{rel}\n')
  patch.extend(difflib.unified_diff(before.splitlines(True),after.splitlines(True),fromfile='a/'+rel,tofile='b/'+rel))
 combined.append(f'diff --git a/{rel} b/{rel}\nnew file mode 100644\n')
 combined.extend(difflib.unified_diff([],after.splitlines(True),fromfile='/dev/null',tofile='b/'+rel))
(H/'review30-after-tsl28.patch').write_text(''.join(patch))
(H/'review30-combined-threefile.patch').write_text(''.join(combined))
(H/'native-supplement.json').write_text(json.dumps(dict(compiled=False,executed=False,original_positive=32,original_negative=4,installed_source_calls=3,additional_positive=names,additional_entry='tex_streaming_mouth_tests.review30_tests',qualification_credit=False),indent=2)+'\n')
